// Generated by gstack /ship Step 9 (pre-landing review, state-machines cells).
//
// Value: protects=close-all closes every open session with reason close-all, charges a held request its worst case
//   and writes one sessions row each; fails_when=close-all skips a session or closeSession drops the in-flight charge;
//   why_new=no test calls /close-all; seam=none; no_claim=the ledger settle (no ledger in this proxy)
// Value: protects=a non-stream client that disconnects is still billed from the upstream usage once it arrives;
//   fails_when=the JSON branch stops accounting when the client leaves, so cost goes unrecorded; why_new=runner.test.ts
//   covers only the streamed cancel; seam=none; no_claim=real provider timing (stub upstream)
// Value: protects=a streamed request to an unreachable upstream returns 529, releases its hold and charges nothing;
//   fails_when=the fetch catch keeps the pending worst case for stream requests; why_new=proxy-paths.test.ts covers only
//   stream:false; seam=none; no_claim=a stream that fails after its headers (a different path)
// Value: protects=a non-stream request still waiting at close is aborted and charged its worst case exactly once;
//   fails_when=the 529 catch path also charges or close forgets the pending entry; why_new=runner.test.ts covers only
//   the streamed request at close; seam=none; no_claim=usage that arrives after close (logged, not added)
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { costMicros, emptyUsage, startProxy, type ProxyConfig } from "../runner/proxy.ts";

const dir = mkdtempSync(join(tmpdir(), "laneb-states-"));
const price = { input: 5, output: 25, cache_write_5m: 6.25, cache_write_1h: 10, cache_read: 0.5 };
const usage = { input_tokens: 900, output_tokens: 120 };

const until = async (check: () => Promise<boolean> | boolean, what: string) => {
  for (let i = 0; i < 250; i++) {
    if (await check()) return;
    await Bun.sleep(20);
  }
  throw new Error("timed out waiting for " + what);
};

describe("proxy session and non-stream request states", () => {
  const received: any[] = [];
  const held: (() => void)[] = [];
  let upstream: ReturnType<typeof Bun.serve>;
  let proxy: ReturnType<typeof startProxy>;
  const logPath = join(dir, "req.jsonl");
  const sessionsPath = join(dir, "sess.jsonl");

  beforeAll(() => {
    upstream = Bun.serve({
      hostname: "127.0.0.1",
      port: 0,
      async fetch(req) {
        const body = (await req.json()) as any;
        received.push(body);
        if (body.metadata?.hold) await new Promise<void>((r) => held.push(r));
        return Response.json({ id: "msg_1", type: "message", role: "assistant", content: [{ type: "text", text: "ok" }], stop_reason: "end_turn", usage });
      },
    });
    const config: ProxyConfig = {
      routes: { stub: { base_url: `http://127.0.0.1:${upstream.port}`, key_env: "FAKE_KEY", auth: "x-api-key", count_tokens: "estimate" } },
      models: { m: { route: "stub", upstream_model: "claude-opus-5-5", price_per_mtok: price } },
    };
    proxy = startProxy({ config, dataHost: "127.0.0.1", dataPort: 0, controlPort: 0, env: { FAKE_KEY: "fake" }, logPath, sessionsPath, closeWaitMs: 200 });
  });

  afterAll(async () => {
    for (const r of held.splice(0)) r();
    await proxy.stop();
    upstream.stop(true);
    rmSync(dir, { recursive: true, force: true });
  });

  const control = () => `http://127.0.0.1:${proxy.control.port}`;
  const open = async () => (await (await fetch(control() + "/sessions", { method: "POST", body: JSON.stringify({ trial: "t", model: "m", cap_usd: 0.5 }) })).json()) as any;
  const message = (token: string, hold: boolean, signal?: AbortSignal) =>
    fetch(`http://127.0.0.1:${proxy.data.port}/v1/messages`, {
      method: "POST",
      signal,
      headers: { "x-api-key": token, "content-type": "application/json" },
      body: JSON.stringify({ model: "m", max_tokens: 1000, stream: false, messages: [{ role: "user", content: "hi" }], metadata: { hold } }),
    });
  const session = async (id: string) => (await (await fetch(control() + `/sessions/${id}`)).json()) as any;
  const logged = (path: string) => readFileSync(path, "utf8").trim().split("\n").map((l) => JSON.parse(l));
  const waitForUpstream = (n: number) => until(() => received.length >= n, `${n} upstream requests`);

  test("a non-stream client that disconnects is still billed from the usage that arrives", async () => {
    const s = await open();
    const ac = new AbortController();
    const pending = message(s.token, true, ac.signal).catch((e) => e);
    await waitForUpstream(received.length + 1);
    ac.abort();
    expect(await pending).toBeInstanceOf(Error);
    held.shift()!();
    const cost = costMicros({ ...emptyUsage(), ...usage }, price);
    await until(async () => (await session(s.id)).spent_micros === cost, "the usage charge");
    const closed = (await (await fetch(control() + `/sessions/${s.id}/close`, { method: "POST", body: "{}" })).json()) as any;
    expect(closed.spent_micros).toBe(cost);
    expect(closed.ok_responses).toBe(1);
    expect(logged(logPath).filter((e) => e.event === "charged_at_worst" && e.session === s.id)).toEqual([]);
  });

  test("a non-stream request still waiting at close is aborted and charged its worst case once", async () => {
    const s = await open();
    const before = received.length;
    const pending = message(s.token, true);
    await waitForUpstream(before + 1);
    const closed = (await (await fetch(control() + `/sessions/${s.id}/close`, { method: "POST", body: "{}" })).json()) as any;
    expect((await pending).status).toBe(529);
    const charged = logged(logPath).filter((e) => e.event === "charged_at_worst" && e.session === s.id);
    expect(charged.length).toBe(1);
    expect(closed.spent_micros).toBe(charged[0].worst_micros);
    expect(closed.ok_responses).toBe(0);
    expect(logged(sessionsPath).filter((r) => r.id === s.id)).toMatchObject([{ spent_micros: charged[0].worst_micros, close_reason: "closed" }]);
    held.shift()!();
  });

  test("a streamed request to an unreachable upstream returns 529 and charges nothing", async () => {
    const probe = Bun.serve({ hostname: "127.0.0.1", port: 0, fetch: () => new Response() });
    const deadPort = probe.port;
    probe.stop(true);
    const dead = startProxy({
      config: { routes: { stub: { base_url: `http://127.0.0.1:${deadPort}`, key_env: "FAKE_KEY", auth: "x-api-key", count_tokens: "estimate" } }, models: { m: { route: "stub", upstream_model: "claude-opus-5-5", price_per_mtok: price } } },
      dataHost: "127.0.0.1", dataPort: 0, controlPort: 0, env: { FAKE_KEY: "fake" }, logPath: join(dir, "dead.jsonl"), sessionsPath: join(dir, "dead-sess.jsonl"), closeWaitMs: 200,
    });
    try {
      const ctl = `http://127.0.0.1:${dead.control.port}`;
      const s = (await (await fetch(ctl + "/sessions", { method: "POST", body: JSON.stringify({ trial: "t", model: "m", cap_usd: 0.05 }) })).json()) as any;
      for (let i = 0; i < 2; i++) {
        const res = await fetch(`http://127.0.0.1:${dead.data.port}/v1/messages`, { method: "POST", headers: { "x-api-key": s.token, "content-type": "application/json" }, body: JSON.stringify({ model: "m", max_tokens: 1000, stream: true, messages: [{ role: "user", content: "hi" }] }) });
        expect(res.status).toBe(529);
        expect(((await res.json()) as any).error.type).toBe("overloaded_error");
      }
      const closed = (await (await fetch(ctl + `/sessions/${s.id}/close`, { method: "POST", body: "{}" })).json()) as any;
      expect(closed).toMatchObject({ requests: 2, ok_responses: 0, refused_budget: 0, spent_micros: 0 });
    } finally {
      await dead.stop();
    }
  });

  test("close-all closes every open session, charges the held request and writes one row each", async () => {
    const idle = await open();
    const busy = await open();
    const before = received.length;
    const pending = message(busy.token, true);
    await waitForUpstream(before + 1);
    const out = (await (await fetch(control() + "/close-all", { method: "POST" })).json()) as any[];
    expect(out.map((r) => r.id).sort()).toEqual([idle.id, busy.id].sort());
    expect(out.every((r) => r.open === false)).toBe(true);
    expect((await pending).status).toBe(529);
    const charged = logged(logPath).filter((e) => e.event === "charged_at_worst" && e.session === busy.id);
    expect(charged.length).toBe(1);
    const rows = logged(sessionsPath).filter((r) => r.id === idle.id || r.id === busy.id);
    expect(rows.length).toBe(2);
    expect(rows.every((r) => r.close_reason === "close-all")).toBe(true);
    expect(rows.find((r) => r.id === idle.id).spent_micros).toBe(0);
    expect(rows.find((r) => r.id === busy.id).spent_micros).toBe(charged[0].worst_micros);
    expect((await (await fetch(control() + "/close-all", { method: "POST" })).json()) as any[]).toEqual([]);
    held.shift()!();
  });
});
